function useFocusLayer(onClose: () => void) { const ref = useRef<HTMLDivElement>(null); const onCloseRef = useRef(onClose); onCloseRef.current = onClose; useEffect(() => { const prior = document.activeElement as HTMLElement | null; const saved = document.body.style.overflow; document.body.style.overflow = "hidden"; ref.current?.querySelector<HTMLElement>("button,input,textarea,select")?.focus(); const handle = (event: KeyboardEvent) => { if (event.key === "Escape") onCloseRef.current(); if (event.key !== "Tab") return; const elements = ref.current?.querySelectorAll<HTMLElement>('button:not([disabled]),input:not([disabled]),textarea:not([disabled]),select:not([disabled]),a[href]'); if (!elements?.length) return; const first = elements[0], last = elements[elements.length - 1]; if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last.focus(); } else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first.focus(); } }; document.addEventListener("keydown", handle); return () => { document.body.style.overflow = saved; document.removeEventListener("keydown", handle); prior?.focus(); }; }, []); return ref; }
function Dialog({ title, children, onClose, wide = false }: { title: string; children: ReactNode; onClose: () => void; wide?: boolean }) { const { t } = useI18n(); const ref = useFocusLayer(onClose); return <div className="modal-overlay" onMouseDown={event => { if (event.target === event.currentTarget) onClose(); }}><div className={`modal ${wide ? "modal-wide" : ""}`} role="dialog" aria-modal="true" aria-label={title} ref={ref}><div className="modal-heading"><div><span className="eyebrow">NEXT MOVE / WORKSPACE</span><h2>{title}</h2></div><button className="icon-button" onClick={onClose} aria-label={t("关闭", "Close")}><X size={20} /></button></div>{children}</div></div>; }

